def compute(vars):
    professional_services_revenue = vars["v1"]
    total_revenue = vars["v2"]

    if total_revenue == 0:
        return None

    ratio = professional_services_revenue / total_revenue
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "professional_services_revenue": professional_services_revenue,
            "total_revenue": total_revenue,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percentage",
                "unit": "percent"
            }
        }
    }
